<script setup lang="ts">
import QuoteLines from '@/shared/ui/QuoteLines.vue'
import RecordList from '@/shared/ui/RecordList.vue'
import DocumentRecognition from '../materials/DocumentRecognition.vue'
import RecognitionSource from '../materials/RecognitionSource.vue'
import type {Workflow} from '../workorders/workflow'
import {computed,nextTick,onActivated,onMounted,onUnmounted,ref,watch} from 'vue'
import {ElDrawer} from 'element-plus'
import {currentUser,httpClient} from '@/shared/http/client'
import {formalPayload,quotationApi,type QuoteCase} from './quotation'
const props=defineProps<{caseId:string;refreshToken?:number;workflow:Workflow;claimNo?:string;insuranceCompany?:string;vehiclePlate?:string;vehicleVin?:string}>(),emit=defineEmits<{changed:[];draft:[value:{assessment:string;markup:string;mode:string}|undefined]}>(),api=quotationApi(httpClient,props.caseId)
const cs=computed(()=>currentUser.value?.roles.includes('CUSTOMER_SERVICE'))
const data=ref<QuoteCase>(),busy=ref(false),message=ref(''),mode=ref<'FIXED_AMOUNT'|'PERCENTAGE'>('FIXED_AMOUNT'),markup=ref('0.00'),assessment=ref(''),historyType=ref('EVENT'),historyPage=ref(1),historyTotal=ref(0),history=ref(''),recognition=ref<InstanceType<typeof DocumentRecognition>>(),drawer=ref(false)
const pending=ref<{body:string;key:string}>()
const fields=ref<Record<string,string>>({}),dirty=ref(false),conflicts=ref<string[]>([]),correction=ref(''),amountInput=ref<HTMLInputElement>()
watch(()=>[dirty.value,assessment.value,markup.value,mode.value],()=>emit('draft',dirty.value?{assessment:assessment.value,markup:markup.value,mode:mode.value}:undefined))
const editingNode=computed(()=>correction.value||props.workflow.currentNode)
const quoteRoot=ref<HTMLElement>(),actionAnchor=ref<HTMLElement>(),docked=ref(true),dockStyle=ref<Record<string,string>>({})
let sizeObserver:ResizeObserver|undefined,actionObserver:IntersectionObserver|undefined
function measureDock(){if(!quoteRoot.value)return;const box=quoteRoot.value.getBoundingClientRect();dockStyle.value={left:Math.max(12,box.left)+'px',width:Math.max(0,Math.min(box.width,window.innerWidth-24))+'px'}}
async function observeDock(){await nextTick();sizeObserver?.disconnect();actionObserver?.disconnect();if(quoteRoot.value){sizeObserver=new ResizeObserver(measureDock);sizeObserver.observe(quoteRoot.value);measureDock()}actionObserver=new IntersectionObserver(([entry])=>{if(entry)docked.value=entry.boundingClientRect.top>window.innerHeight-90},{rootMargin:'0px 0px -90px 0px',threshold:0});const anchor=quoteRoot.value?.closest('.task-surface')?.querySelector('.task-end')??actionAnchor.value;if(anchor)actionObserver.observe(anchor)}
const title=computed(()=>props.workflow.nodes.find(n=>n.key===props.workflow.currentNode)?.label??'报价记录')
function candidates(candidate:Record<string,unknown>){const incoming=(candidate.fields??{}) as Record<string,string>;const extracted={claimNo:incoming.claimNo??'',insuranceCompany:incoming.insuranceCompany??'',vehiclePlate:incoming.vehiclePlate??'',vehicleVin:incoming.vehicleVin??incoming.vehicleIdentifier??''};for(const [key,value] of Object.entries(extracted)){if(!fields.value[key])fields.value[key]=value;else if(value&&fields.value[key]!==value)message.value='识别内容与当前核对信息不同，已保留输入，请核对原件'}conflicts.value=['claimNo','insuranceCompany','vehiclePlate','vehicleVin'].filter(k=>fields.value[k]&&props[k as 'claimNo']&&fields.value[k]!==props[k as 'claimNo']).map(k=>({claimNo:'报案号',insuranceCompany:'保险公司',vehiclePlate:'车牌号',vehicleVin:'车架号'})[k as 'claimNo']);const amount=String(incoming.amountCandidate??candidate.amountCandidate??'');if(!dirty.value)assessment.value=amount;else if(amount&&assessment.value!==amount)message.value='识别金额与当前输入不同，请核对原件，保留当前输入'}
async function load(){const next=await api.get();if(dirty.value&&data.value&&next.version!==data.value.version)message.value='报价或核损依据已变化，已保留输入，请重新核对当前版本';data.value=next;if(!dirty.value&&data.value.assessment)assessment.value=data.value.assessment.amount}
async function run(action:()=>Promise<void>){if(busy.value)return;busy.value=true;message.value='';try{await action()}catch(e){message.value=e instanceof Error?e.message:'操作失败'}finally{busy.value=false}}
async function post(path:string,body:unknown){const serialized=JSON.stringify({path,body});if(pending.value?.body!==serialized)pending.value={body:serialized,key:crypto.randomUUID()};data.value=await api.post(path,body,pending.value.key);pending.value=undefined;dirty.value=false;message.value='已保存';correction.value='';emit('changed')}
async function proceed(){
 const latest=(await httpClient.get<{data:Workflow}>(`/work-orders/${props.caseId}/workflow`)).data.data
 if((!latest.canAct&&!correction.value)||latest.currentNode!==props.workflow.currentNode)throw Error('任务已变化，请刷新当前节点')
 if(!data.value)return
 if(editingNode.value==='QUOTE_REVIEW')await post('formal-quotes',formalPayload(data.value.version,data.value.rawQuote?.id??'',mode.value,markup.value))
 else if(editingNode.value==='INSURER_ASSESSMENT'){
  if(!/^(?:0|[1-9][0-9]*)(?:\.[0-9]{1,2})?$/.test(assessment.value)){amountInput.value?.focus();throw Error('请填写有效最终核损金额，最多2位小数')}
  if(!recognition.value){drawer.value=true;throw Error('请上传核损单并核对原件与采用信息')}
  const link=await recognition.value.confirm(assessment.value,fields.value)
  await post('recognized-assessment',{...link,assessment:{expectedVersion:data.value.version,amount:assessment.value}});drawer.value=false
 }else if(latest.currentNode==='REPAIR_AUTHORIZATION')await post(`confirmations/${data.value.gate.insurerConfirmationRecorded?'CUSTOMER_SERVICE':'INSURER'}`,{expectedVersion:data.value.version})
}
async function loadHistory(){const result=await api.history(historyType.value,historyPage.value);historyTotal.value=result.total;history.value=JSON.stringify(result.records,null,2)}
async function exportFile(kind:'pdf'|'csv'){if(!data.value?.formalQuote)return;const blob=kind==='pdf'?await api.pdf(data.value.formalQuote.id):await api.export(data.value.formalQuote.id),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`formal-quote-v${data.value.formalQuote.version}.${kind}`;a.click();URL.revokeObjectURL(url)}
onMounted(async()=>{await run(load);await observeDock();window.addEventListener('resize',measureDock)});onUnmounted(()=>{sizeObserver?.disconnect();actionObserver?.disconnect();window.removeEventListener('resize',measureDock)});onActivated(async()=>{await run(load);await observeDock()});watch(()=>props.refreshToken,()=>void run(load));watch(()=>props.workflow.currentNode,()=>{if(dirty.value)message.value='流程已更新，未提交信息保留，请核对当前任务';void run(load)})
</script>
<template><section ref="quoteRoot" class="quotation"><h2>{{ title }}</h2><p v-if="message" role="alert" class="inline-error">{{ message }} <button v-if="!data" @click="run(load)">重试</button></p><template v-if="data"><section data-reading="报价依据"><h3>报价依据</h3><details v-if="data.rawQuote" :open="editingNode==='QUOTE_REVIEW'"><summary>网点报价 <strong>{{ data.rawQuote.total }} 元</strong> · 查看明细与原件</summary><QuoteLines :lines="data.rawQuote.lines"/><RecognitionSource :case-id="caseId" :business-id="data.rawQuote.id"/></details><p v-else>等待网点提交报价原件和核对信息。</p><details v-if="data.formalQuote"><summary>正式报价 · {{ data.formalQuote.total }} 元</summary><p>原始 {{ data.formalQuote.originalTotal }} · 加价 {{ data.formalQuote.markupAmount }} 元</p><QuoteLines :lines="data.formalQuote.lines" formal/><button :disabled="busy" @click="run(()=>exportFile('pdf'))">下载报价单</button><button :disabled="busy" @click="run(()=>exportFile('csv'))">导出明细</button></details></section>
<section v-if="cs&&editingNode==='QUOTE_REVIEW'" data-reading="审核信息"><h3>审核报价</h3><label>加价方式<select v-model="mode" @change="dirty=true"><option value="FIXED_AMOUNT">固定金额（元）</option><option value="PERCENTAGE">百分比（%）</option></select></label><label>{{ mode==='FIXED_AMOUNT'?'加价金额（元）':'加价比例（%）' }}<input v-model="markup" inputmode="decimal" @input="dirty=true"/></label><p>只调整总额，网点项目单价保留。</p></section>
<section v-if="editingNode==='INSURER_ASSESSMENT'" data-reading="核损信息"><h3>核损信息</h3><button v-if="cs" @click="drawer=true">上传与核对核损单</button><label>最终核损金额（元）<input ref="amountInput" v-model="assessment" :disabled="!cs" inputmode="decimal" @input="dirty=true"/></label><p v-if="conflicts.length" role="alert">原件与案件信息不同：{{ conflicts.join('、') }}。请核对原件；原案件信息保留。</p><p v-if="data.assessment">已录入 {{ data.assessment.amount }} 元</p><ElDrawer v-model="drawer" title="核损原件与信息核对" size="min(620px, 96vw)" :destroy-on-close="false"><DocumentRecognition ref="recognition" :case-id="caseId" category="LOSS_ASSESSMENT" :assignment-version="data.assignmentVersion" @candidate="candidates" @changed="emit('changed')"/><div class="loss-field" v-for="item in [{key:'claimNo',name:'报案号'},{key:'insuranceCompany',name:'保险公司'},{key:'vehiclePlate',name:'车牌号'},{key:'vehicleVin',name:'车架号'}]" :key="item.key"><label>{{ item.name }}<input v-model="fields[item.key]"/></label></div><label>采用核损金额（元）<input v-model="assessment" inputmode="decimal" @input="dirty=true"/></label><button @click="drawer=false">返回核损任务</button></ElDrawer></section>
<details v-if="cs&&data.formalQuote&&['WAITING_INSURER_ASSESSMENT','WAITING_REPAIR_AUTHORIZATION'].includes(data.status)"><summary>修正资料</summary><p>修正后原确认失效，需重新确认。</p><button :disabled="busy" @click="correction='QUOTE_REVIEW'">修正报价</button><button :disabled="busy" @click="correction='INSURER_ASSESSMENT'">修正核损</button><button v-if="correction" @click="correction=''">取消修正</button></details><RecognitionSource v-if="data.assessment" :case-id="caseId" :business-id="data.assessment.id"/><section v-if="workflow.currentNode==='REPAIR_AUTHORIZATION'" data-reading="授权条件"><h3>授权条件</h3><ul class="gate-list"><li v-for="item in [{key:'lossAssessmentFileUploaded',name:'核损单'},{key:'finalAssessmentAmountRecorded',name:'最终核损金额'},{key:'insurerConfirmationRecorded',name:'保险公司确认'},{key:'customerServiceConfirmationRecorded',name:'客服确认'}]" :key="item.key"><span>{{ item.name }}</span><strong :class="data.gate[item.key as keyof typeof data.gate]?'complete':'missing'">{{ data.gate[item.key as keyof typeof data.gate]?'已满足':'待办理' }}</strong></li></ul><p v-if="data.authorized">等待网点开始维修。</p></section>
<details><summary>版本记录</summary><select v-model="historyType"><option value="RAW">网点报价</option><option value="FORMAL">正式报价</option><option value="ASSESSMENT">核损</option><option value="CONFIRMATION">确认</option><option value="EVENT">变更记录</option></select><button :disabled="busy" @click="run(loadHistory)">查询</button><RecordList :value="history"/><button :disabled="busy||historyPage===1" @click="historyPage--;run(loadHistory)">上一页</button><span>第 {{ historyPage }} 页 · 共 {{ historyTotal }} 条</span><button :disabled="busy||historyPage*20>=historyTotal" @click="historyPage++;run(loadHistory)">下一页</button></details>
<div ref="actionAnchor" class="action-anchor"/><footer class="workflow-action" :class="{docked}" :style="docked?dockStyle:undefined"><span>{{ workflow.canAct?'核对信息后继续':workflow.actorRole==='REPAIR_SHOP'?'等待网点处理':'当前仅查看' }}</span><button v-if="(workflow.canAct||correction)&&cs" class="primary" :disabled="busy" @click="run(proceed)">{{ busy?'正在保存…':!correction&&workflow.currentNode==='REPAIR_AUTHORIZATION'?(data.gate.insurerConfirmationRecorded?'客服确认':'记录保险确认'):'继续' }}</button></footer></template><div v-else-if="busy" class="quote-skeleton" aria-busy="true"><span/><span/><span/></div></section></template>
<style scoped>.quotation{display:flex;flex-direction:column;padding:0 0 74px;min-width:0}.quotation>*{order:3}.quotation>h2,.quotation>.inline-error{order:0}.quotation>section[data-reading="核损信息"],.quotation>section[data-reading="审核信息"],.quotation>section[data-reading="授权条件"]{order:1}.quotation>section[data-reading="报价依据"]{order:2}.quotation>.action-anchor{order:8}.quotation>.workflow-action{order:9}.quotation h2{font-size:24px;margin:0 0 24px}.quotation h3{font-size:17px;margin:0 0 14px}.quotation section{padding:18px 0;border-top:1px solid #dce5e4;scroll-margin-top:180px}.quotation label,.loss-field label{display:grid;gap:8px;margin:16px 0;font-size:13px}.quotation input,.quotation select,.loss-field input{padding:10px;border:1px solid #bccccc;border-radius:6px;max-width:100%;font:inherit}.quotation button{margin:6px 8px 6px 0}.quotation details{margin:18px 0}.quotation summary{cursor:pointer}.quotation p{color:#536a6b;font-size:13px}.gate-list{padding:0;list-style:none}.gate-list li{display:flex;justify-content:space-between;gap:16px;border-bottom:1px solid #dce5e4;padding:14px 0}.complete{color:#236b4b}.missing,.inline-error{color:#a7313c}.action-anchor{height:1px}.workflow-action.docked{position:fixed;bottom:16px;margin:0;box-sizing:border-box}.workflow-action{position:relative;display:flex;justify-content:space-between;align-items:center;gap:16px;margin:32px -12px 0;padding:14px 18px;border:1px solid #fff;background:rgba(245,250,248,.94);backdrop-filter:blur(12px);box-shadow:inset 0 1px #fff,0 6px 24px #30595112;border-radius:12px;z-index:2}.workflow-action span{font-size:12px;color:#536a6b}.workflow-action .primary{background:#42685f;color:#fff;border-color:#42685f;min-width:100px}.quote-skeleton{display:grid;gap:20px}.quote-skeleton span{height:56px;background:#e8eeee;border-radius:8px}@media(prefers-reduced-transparency:reduce){.workflow-action{background:#fff;backdrop-filter:none}}button:active{transform:scale(.98)}@media(prefers-reduced-motion:reduce){button:active{transform:none}}</style>
